                return dist_matrix[a][b]
            except Exception:
                pass
        if a in xy and b in xy:
            pa = xy[a]
            pb = xy[b]
            dx = pa[0] - pb[0]
            dy = pa[1] - pb[1]
            return (dx * dx + dy * dy) ** 0.5
        return abs(a - b)

    def route_load(rt):
        s = 0
        for c in rt:
            s += demand_of(c)
        return s

    def route_cost(rt):
        if not rt:
            return 0
        cost = dist(depot, rt[0])
        for i in range(len(rt) - 1):
            cost += dist(rt[i], rt[i + 1])
        cost += dist(rt[-1], depot)
        return cost

    def route_savings_insert_pos(rt, c):
        best_pos = 0
        best_delta = None
        if not rt:
            return 0, 0
        for i in range(len(rt) + 1):
            a = depot if i == 0 else rt[i - 1]
            b = depot if i == len(rt) else rt[i]
            delta = dist(a, c) + dist(c, b) - dist(a, b)
            if best_delta is None or delta < best_delta:
                best_delta = delta
                best_pos = i
        return best_pos, best_delta

    if depot in xy:
        dx, dy = xy[depot][0], xy[depot][1]
        customer_ids.sort(key=lambda c: (0 if c in xy else 1,
                                         ((xy[c][1] - dy) if c in xy else 0),
                                         ((xy[c][0] - dx) if c in xy else 0),
                                         demand_of(c), c))
    else:
        customer_ids.sort(key=lambda c: (-demand_of(c), c))

    unassigned = customer_ids[:]
    routes = []

    while unassigned:
        seed = unassigned[0]
        best_key = None
        for c in unassigned:
            key = (dist(depot, c), -demand_of(c), c)
            if best_key is None or key < best_key:
                best_key = key
                seed = c

        rt = [seed]
        unassigned.remove(seed)
        load = demand_of(seed)

        improved = True
        while improved and unassigned:
            improved = False
            best_c = None
            best_score = None
            for c in unassigned:
                d = demand_of(c)
                if capacity > 0 and load + d > capacity:
                    continue
                pos, delta = route_savings_insert_pos(rt, c)
                score = (delta, dist(rt[-1], c), d, c)
                if best_score is None or score < best_score:
                    best_score = score
                    best_c = c
            if best_c is not None:
                rt.append(best_c)
                unassigned.remove(best_c)
                load += demand_of(best_c)
                improved = True

        routes.append(rt)

    if capacity <= 0:
        return routes

    # Repair any overloads by splitting routes.
    repaired = []
    for rt in routes:
        if route_load(rt) <= capacity:
            repaired.append(rt)
            continue
        cur = []
        load = 0
        for c in rt:
            d = demand_of(c)
            if cur and load + d > capacity:
                repaired.append(cur)
                cur = [c]
                load = d
            else:
                cur.append(c)
                load += d
        if cur:
            repaired.append(cur)
    routes = repaired

    # Cross-route relocate / swap
    changed = True
    limit = 2 * len(customer_ids) + 5
    while changed and limit > 0:
        limit -= 1
        changed = False
        # relocate from expensive routes to improve total cost
        for i in range(len(routes)):
            ri = routes[i]
            if not ri:
                continue
            for a_idx in range(len(ri)):
                a = ri[a_idx]
                da = demand_of(a)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    lj = route_load(rj)
                    if lj + da > capacity:
                        continue
                    base_i = route_cost(ri)
                    base_j = route_cost(rj)
                    new_ri = ri[:a_idx] + ri[a_idx + 1:]
                    pos, _ = route_savings_insert_pos(rj, a)
                    new_rj = rj[:pos] + [a] + rj[pos:]
                    if route_cost(new_ri) + route_cost(new_rj) + 1e-12 < base_i + base_j:
                        routes[i] = new_ri
                        routes[j] = new_rj
                        changed = True
                        break
                if changed:
                    break
            if changed:
                break

        # swap if beneficial and feasible
        if not changed:
            for i in range(len(routes)):
                for j in range(i + 1, len(routes)):
                    ri = routes[i]
                    rj = routes[j]
                    li = route_load(ri)
                    lj = route_load(rj)
                    base = route_cost(ri) + route_cost(rj)
                    for a_idx in range(len(ri)):
                        a = ri[a_idx]
                        da = demand_of(a)
                        for b_idx in range(len(rj)):
                            b = rj[b_idx]
                            db = demand_of(b)
                            if li - da + db > capacity or lj - db + da > capacity:
                                continue
                            nri = ri[:a_idx] + [b] + ri[a_idx + 1:]
                            nrj = rj[:b_idx] + [a] + rj[b_idx + 1:]
                            if route_cost(nri) + route_cost(nrj) + 1e-12 < base:
                                routes[i] = nri
                                routes[j] = nrj
                                changed = True
                                break
                        if changed:
                            break
                    if changed:
                        break
                if changed:
                    break

    return [rt for rt in routes if rt]
